import { geminiUsProxy } from "./gemini-proxy.js";

const DEFAULT_MODEL = "gemini-3.8-flash";
const RETRYABLE_STATUS = new Set([429, 500, 502, 503, 504]);

const KEY_ENV = {
  1: "GEMINI_API_KEY_1",
  2: "GEMINI_API_KEY_2",
  3: "GEMINI_API_KEY_3",
  4: "GEMINI_API_KEY_4",
  5: "GEMINI_API_KEY_5"
};

// After Gemini rejects this Worker's location, send requests through the US
// proxy for a while instead of failing first every time (per isolate).
const LOCATION_ERROR = /location is not supported/i;
const PROXY_FOR_MS = 10 * 60 * 1000;
let proxyUntil = 0;

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

function retryDelay(response, attempt) {
  const retryAfter = Number(response.headers.get("Retry-After") || 0);
  if (retryAfter > 0) return Math.min(retryAfter * 1000, 5000);
  const exponential = Math.min(5000, 300 * (2 ** attempt));
  return exponential + Math.floor(Math.random() * 250);
}

async function readError(response) {
  const text = await response.text();
  let detail = text;
  try {
    const parsed = JSON.parse(text);
    detail = parsed?.error?.message || text;
  } catch {}
  return detail.slice(0, 1600);
}

export function getGeminiKeyStatus(env) {
  return Object.fromEntries(
    Object.entries(KEY_ENV).map(([slot, envName]) => [`key${slot}`, Boolean(env?.[envName])])
  );
}

export async function callGemini(env, keySlot, {
  system,
  prompt,
  schema,
  temperature = 0.3,
  maxOutputTokens,
  model: modelOverride,
  tools,
  timeoutMs = 90000,
  contents,
  maxAttempts = 4
}) {
  // keySlot is a numbered slot (1-5) or the name of a Worker secret.
  const envName = KEY_ENV[keySlot] || keySlot;
  const apiKey = env?.[envName];
  const model = modelOverride || env?.GEMINI_MODEL || DEFAULT_MODEL;

  if (!apiKey) {
    throw new Error(`${envName} is not configured.`);
  }

  const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`;
  const body = {
    systemInstruction: { parts: [{ text: system }] },
    // `contents` carries a multi-turn or multimodal conversation; `prompt` is a single text turn.
    contents: contents || [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig: {
      responseMimeType: "application/json",
      responseSchema: schema,
      temperature
    }
  };

  if (maxOutputTokens) body.generationConfig.maxOutputTokens = maxOutputTokens;
  if (tools) body.tools = tools;

  let lastError = null;
  const proxy = geminiUsProxy(env);
  let triedProxy = false;

  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    const viaProxy = Boolean(proxy) && (triedProxy || Date.now() < proxyUntil);
    const init = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-goog-api-key": apiKey
      },
      body: JSON.stringify(body)
    };
    const response = viaProxy
      ? await proxy.fetch(endpoint, init)
      : await fetch(endpoint, { ...init, signal: AbortSignal.timeout(timeoutMs) });

    if (response.ok) {
      const raw = await response.text();
      let payload;
      try {
        payload = JSON.parse(raw);
      } catch {
        throw new Error("Gemini returned invalid JSON.");
      }

      // Grounded responses can split the answer across several text parts.
      const text = (payload?.candidates?.[0]?.content?.parts || [])
        .filter(part => typeof part.text === "string" && !part.thought)
        .map(part => part.text)
        .join("");
      if (!text) {
        throw new Error(
          `Gemini returned no content (finishReason=${payload?.candidates?.[0]?.finishReason || "unknown"}).`
        );
      }

      try {
        return JSON.parse(text);
      } catch {
        throw new Error("Gemini response body was not valid JSON.");
      }
    }

    const detail = await readError(response);
    lastError = new Error(`Gemini HTTP ${response.status}: ${detail}`);

    // Wrong Cloudflare location: retry once at once through the US proxy.
    if (response.status === 400 && LOCATION_ERROR.test(detail) && proxy && !viaProxy && !triedProxy) {
      triedProxy = true;
      proxyUntil = Date.now() + PROXY_FOR_MS;
      attempt -= 1;
      continue;
    }

    if (!RETRYABLE_STATUS.has(response.status) || attempt === maxAttempts - 1) {
      throw lastError;
    }

    await sleep(retryDelay(response, attempt));
  }

  throw lastError || new Error("Gemini request failed.");
}

export async function runWorkerFanout(env, requests) {
  // K2/K3/K4 are logically independent. A tiny stagger smooths the burst
  // without turning the build into a slow sequential pipeline.
  return Promise.all([
    callGemini(env, 2, requests[2]),
    sleep(150).then(() => callGemini(env, 3, requests[3])),
    sleep(300).then(() => callGemini(env, 4, requests[4]))
  ]);
}
